import dis_like

# 极简栈式虚拟机：每条指令对操作数栈做一次变换
class VM:
    def __init__(self, code, consts):
        self.code = code        # 指令流：[(op, arg), ...]
        self.consts = consts    # 常量池：下标 -> 值
        self.stack = []
        self.pc = 0             # 指令指针

    def run(self):
        while self.pc < len(self.code):
            op, arg = self.code[self.pc]
            self.pc += 1
            if op == "LOAD_CONST":
                self.stack.append(self.consts[arg])       # 压入常量
            elif op == "ADD":
                b, a = self.stack.pop(), self.stack.pop()
                self.stack.append(a + b)                  # 栈式加法
            elif op == "PRINT":
                print(self.stack.pop())                   # 弹出并打印
            elif op == "JUMP_IF_FALSE":
                if not self.stack.pop():
                    self.pc = arg                         # 条件跳转修改指令指针
            else:
                raise RuntimeError(f"unknown opcode: {op}")
        return self.stack

# (2 + 3) * 4 的字节码
code = [
    ("LOAD_CONST", 0), ("LOAD_CONST", 1), ("ADD", None),
    ("LOAD_CONST", 2), ("MUL", None), ("PRINT", None),
]
VM(code, [2, 3, 4]).run()

def evaluate(node, env):
    """树遍历求值：表达式与语句共用一套环境链。"""
    kind = node["kind"]
    if kind == "number":
        return node["value"]
    if kind == "variable":
        if node["name"] not in env:
            raise MiniLangError(f"undefined variable '{node['name']}'", node["line"], node["column"])
        return env.lookup(node["name"])
    if kind == "binary":
        left = evaluate(node["left"], env)
        right = evaluate(node["right"], env)
        if node["op"] == "+": return left + right
        if node["op"] == "-": return left - right
        if node["op"] == "*": return left * right
        if node["op"] == "/":
            if right == 0:
                raise MiniLangError("division by zero", node["line"], node["column"])
            return left / right
    if kind == "assign":
        env.define(node["name"], evaluate(node["value"], env))
        return None
    if kind == "if":
        branch = node["then"] if evaluate(node["cond"], env) else node["else"]
        return evaluate(branch, env.child())
    raise MiniLangError(f"unsupported node: {kind}", node.get("line", 0), node.get("column", 0))
